{
  "id": "ww-00008",
  "version": "0.1",
  "concept_id": "ww-00008",
  "identity": {
    "name": "RevvLot",
    "tagline": "Old School Hustle. New School Wheels.",
    "one_line_description": "RevvLot is a retro-styled used car marketplace where buyers browse, inspect, and reserve quality pre-owned vehicles with full transparency and zero dealership drama.",
    "domain": "automotive_mobility",
    "subdomain": "used car marketplace",
    "voice": [
      "bold",
      "nostalgic",
      "straight-talking",
      "energetic",
      "trustworthy"
    ],
    "target_audience": "Budget-conscious car buyers aged 25\u201345 who are skeptical of traditional dealerships, comfortable browsing online, and want full vehicle details before ever setting foot on a lot."
  },
  "pages": [
    {
      "slug": "home",
      "title": "Home",
      "role": "landing",
      "goal": "Hook first-time visitors with the RevvLot brand energy, communicate the value of a no-nonsense used car marketplace, and funnel them toward browsing inventory.",
      "meta_description": "RevvLot is the retro-cool used car marketplace where you find, inspect, and reserve quality pre-owned vehicles \u2014 no pressure, no games, just great deals.",
      "sections": [
        {
          "id": "home-section-1",
          "type": "hero",
          "intent": "Deliver an immediate brand punch that communicates the retro personality and core value proposition \u2014 real cars, real prices, zero dealership hassle.",
          "eyebrow": "Welcome to the Lot",
          "headline": "Find Your Next Ride. No Haggling Required.",
          "subheadline": "Thousands of inspected, priced-right used cars \u2014 browsed from your couch, reserved in minutes.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "Browse the Inventory",
              "target_page": "product"
            },
            {
              "label": "How It Works",
              "target_page": "home"
            }
          ],
          "asset_ideas": [
            {
