input.content:
/* RevvLot — Retro 90s Used Car Marketplace */

@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');

/* ---------- TOKENS ---------- */
:root {
  --grape: #6600CC;
  --lime: #00FF33;
  --magenta: #FF00CC;
  --sky: #00CCFF;
  --honk: #FFFF00;
  --bevel: #E8E8E8;
  --chrome: #C0C0C0;
  --midnight: #110022;
  --shadow-edge: #808080;
  --bevel-light: #FFFFFF;
  --font-head: 'Arial Black', 'Arial Bold', Gadget, sans-serif;
  --font-body: 'Verdana', 'Geneva', Tahoma, sans-serif;
  --font-pixel: 'VT323', 'Courier New', monospace;
}

/* ---------- RESET ---------- */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  overflow-x: hidden;
}

body {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.65;
  color: var(--bevel);
  background: var(--midnight);
}

a {
  color: var(--sky);
  text-decoration: underline;
}

img, svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ---------- LAYOUT HELPERS ---------- */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 32px;
}

.eyebrow {
  display: inline-block;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  background: var(--honk);
  color: var(--midnight);
  padding: 4px 10px;
}

.eyebrow-pixel {
  display: inline-block;
  font-family: var(--font-pixel);
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--honk);
}

.eyebrow-pixel.sky { color: var(--sky); }
.eyebrow-pixel.magenta { color: var(--magenta); }
.eyebrow-pixel.grape { color: var(--grape); }

.eyebrow-pixel::after {
  content: ' ▮';
  animation: blink 1s steps(1) infinite;
}

@keyframes blink {
  50% { opacity: 0; }
}

/* ---------- BEVELED BUTTON (WIN95) ---------- */
.btn {
  display: inline-block;
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 14px;
  text-decoration: none;
  letter-spacing: 0.02em;
  padding: 12px 24px;
  background: var(--lime);
  color: var(--midnight);
  border: 0;
  border-top: 3px solid var(--bevel-light);
  border-left: 3px solid var(--bevel-light);
  border-bottom: 3px solid var(--shadow-edge);
  border-right: 3px solid var(--shadow-edge);
  box-shadow: 2px 2px 0 var(--midnight);
  transition: transform 0.05s linear;
}

.btn:hover {
  filter: brightness(1.05);
}

.btn:active {
  border-top-color: var(--shadow-edge);
  border-left-color: var(--shadow-edge);
  border-bottom-color: var(--bevel-light);
  border-right-color: var(--bevel-light);
}

.btn--secondary {
  background: var(--bevel);
  color: var(--midnight);
}

.btn--dark {
  background: var(--midnight);
  color: var(--honk);
}

.btn--big {
  font-size: 18px;
  padding: 16px 28px;
  border-width: 4px;
}

.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 24px;
}

/* ---------- BEVELED PANEL ---------- */
.panel {
  background: var(--bevel);
  color: var(--midnight);
  border-top: 3px solid var(--bevel-light);
  border-left: 3px solid var(--bevel-light);
  border-bottom: 3px solid var(--shadow-edge);
  border-right: 3px solid var(--shadow-edge);
  outline: 1px solid var(--chrome);
}

.panel-recessed {
  background: var(--bevel);
  border-top: 2px solid var(--shadow-edge);
  border-left: 2px solid var(--shadow-edge);
  border-bottom: 2px solid var(--bevel-light);
  border-right: 2px solid var(--bevel-light);
}

/* ---------- RAINBOW RULE ---------- */
.rainbow-rule {
  height: 18px;
  width: 100%;
  background: linear-gradient(
    to bottom,
    #FF0000 0 3px,
    #FF8800 3px 6px,
    var(--honk) 6px 9px,
    var(--lime) 9px 12px,
    var(--sky) 12px 15px,
    var(--magenta) 15px 18px
  );
  border: 0;
  display: block;
}

.rainbow-rule--thin {
  height: 4px;
  background: linear-gradient(
    to right,
    var(--lime) 0 25%,
    var(--magenta) 25% 50%,
    var(--sky) 50% 75%,
    var(--honk) 75% 100%
  );
}

/* ---------- 88x31 BADGE ---------- */
.badge88 {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 88px;
  height: 31px;
  font-family: var(--font-pixel);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  text-align: center;
  background: var(--honk);
  color: var(--midnight);
  border: 2px solid var(--sky);
  line-height: 1.05;
  padding: 0 4px;
}

.badge88--lime {
  background: var(--lime);
  border-color: var(--midnight);
  color: var(--midnight);
}

.badge88--sky {
  background: var(--sky);
  border-color: var(--midnight);
  color: var(--midnight);
}

.badge88--dark {
  background: var(--midnight);
  border-color: var(--magenta);
  color: var(--bevel);
}

.badge88--ssl {
  background: var(--midnight);
  border-color: var(--lime);
  color: var(--lime);
}

.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

/* ---------- HEADER / NAV ---------- */
.site-nav {
  background: var(--midnight);
  border-bottom: 4px solid var(--lime);
  position: relative;
  z-index: 50;
}

.site-nav__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 32px;
  flex-wrap: wrap;
  gap: 16px;
}

.site-nav__brand {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 26px;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--lime);
  text-decoration: none;
  text-shadow: 2px 2px 0 var(--magenta);
}

.site-nav__brand .dot {
  color: var(--magenta);
}

.site-nav__links {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.site-nav__links a {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 12px;
  letter-spacing: 0.05em;
  color: var(--bevel);
  background: var(--midnight);
  padding: 8px 12px;
  text-decoration: none;
  border: 2px solid var(--chrome);
  border-bottom-color: var(--shadow-edge);
  border-right-color: var(--shadow-edge);
}

.site-nav__links a:hover,
.site-nav__links a.is-active {
  background: var(--honk);
  color: var(--midnight);
  border-color: var(--midnight);
}

.site-nav__counter {
  font-family: var(--font-pixel);
  font-size: 13px;
  color: var(--lime);
  background: #000;
  padding: 4px 8px;
  border-top: 2px solid var(--shadow-edge);
  border-left: 2px solid var(--shadow-edge);
  border-bottom: 2px solid var(--bevel);
  border-right: 2px solid var(--bevel);
}

/* ---------- FOOTER ---------- */
.site-footer {
  background: var(--midnight);
  color: var(--bevel);
  padding: 32px 0 24px;
  border-top: 4px solid var(--magenta);
  font-size: 13px;
}

.site-footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 32px;
  align-items: start;
}

.site-footer h4 {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 14px;
  color: var(--lime);
  margin-bottom: 8px;
}

.site-footer ul li {
  padding: 2px 0;
}

.site-footer ul a {
  color: var(--sky);
  font-size: 13px;
}

.site-footer__bottom {
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px dashed var(--chrome);
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--honk);
}

.site-footer__brand {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 22px;
  text-transform: uppercase;
  color: var(--magenta);
  text-shadow: 2px 2px 0 var(--lime);
  margin-bottom: 8px;
}

.under-construction-strip {
  background: repeating-linear-gradient(
    -45deg,
    var(--honk) 0 16px,
    var(--midnight) 16px 32px
  );
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--midnight);
  padding: 4px 8px;
  text-align: center;
  text-transform: uppercase;
  font-weight: bold;
}

/* ---------- MARQUEE ---------- */
.marquee {
  background: var(--midnight);
  color: var(--lime);
  padding: 8px 0;
  overflow: hidden;
  white-space: nowrap;
  border-top: 1px solid var(--lime);
  border-bottom: 1px solid var(--lime);
  font-family: var(--font-pixel);
  font-size: 14px;
}

.marquee__track {
  display: inline-block;
  padding-left: 100%;
  animation: marquee 30s linear infinite;
}

.marquee__track span {
  margin-right: 48px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.marquee__track .star {
  color: var(--honk);
}

@keyframes marquee {
  0% { transform: translate3d(0, 0, 0); }
  100% { transform: translate3d(-100%, 0, 0); }
}

/* ---------- HERO MARQUEE BACKDROP ---------- */
.hero-marquee {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}

.hero-marquee__row {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 120px;
  text-transform: uppercase;
  letter-spacing: -0.04em;
  white-space: nowrap;
  opacity: 0.22;
  animation: marquee 30s linear infinite;
}

.hero-marquee__row--magenta {
  color: var(--magenta);
}

.hero-marquee__row--lime {
  color: var(--lime);
  animation-direction: reverse;
  animation-duration: 26s;
}

/* ---------- HOME PAGE ---------- */
.home-hero {
  position: relative;
  background: var(--midnight);
  min-height: 90vh;
  padding: 64px 0 64px;
  overflow: hidden;
}

.home-hero__inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 5fr 7fr;
  gap: 32px;
  align-items: end;
  min-height: 70vh;
}

.home-hero__copy {
  align-self: end;
  padding-bottom: 16px;
}

.home-hero__headline {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 64px;
  line-height: 0.95;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--bevel);
  text-shadow: 3px 3px 0 var(--magenta);
  margin: 16px 0 16px;
}

.home-hero__headline .lime-dot { color: var(--lime); }

.home-hero__sub {
  max-width: 480px;
  font-size: 16px;
  color: var(--bevel);
  margin-bottom: 24px;
}

.home-hero__art {
  position: relative;
  align-self: end;
  height: 460px;
}

.home-hero__art svg {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 0 18px rgba(255, 0, 204, 0.35));
}

.home-hero__sticker {
  position: absolute;
  right: 16px;
  bottom: 24px;
  z-index: 3;
  transform: rotate(-6deg);
}

/* ---------- SECTION FRAMES ---------- */
section {
  position: relative;
}

.section--midnight { background: var(--midnight); }
.section--grape { background: var(--grape); }
.section--bevel { background: var(--bevel); color: var(--midnight); }
.section--magenta { background: var(--magenta); color: var(--midnight); }

.section-pad {
  padding: 80px 0;
}

.section-header {
  margin-bottom: 32px;
}

.section-header h2 {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 42px;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  line-height: 1;
  margin: 12px 0 8px;
}

.section-header h2.lime { color: var(--lime); text-shadow: 2px 2px 0 var(--magenta); }
.section-header h2.magenta { color: var(--magenta); text-shadow: 2px 2px 0 var(--bevel); }
.section-header h2.bevel { color: var(--bevel); }
.section-header h2.honk { color: var(--honk); text-shadow: 3px 3px 0 var(--midnight); }
.section-header h2.midnight { color: var(--midnight); }
.section-header h2.sky { color: var(--sky); }

.section-header p {
  max-width: 720px;
  font-size: 16px;
  color: inherit;
}

.section-header.center {
  text-align: center;
}

.section-header.center p {
  margin-left: auto;
  margin-right: auto;
}

.center-wrap {
  display: flex;
  justify-content: center;
}

/* ---------- STATS GRID ---------- */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  margin-top: 40px;
}

.stat-block {
  text-align: center;
  padding: 16px;
  border-right: 1px solid var(--chrome);
  position: relative;
}

.stat-block:last-child {
  border-right: none;
}

.stat-block__tag {
  font-family: var(--font-pixel);
  color: var(--honk);
  font-size: 13px;
  letter-spacing: 0.15em;
}

.stat-block__value {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 72px;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--lime);
  text-shadow: 2px 2px 0 var(--magenta);
  margin: 8px 0;
}

.stat-block__desc {
  color: var(--bevel);
  font-size: 13px;
  max-width: 200px;
  margin: 0 auto;
}

.stats-headline-rule {
  display: block;
  height: 4px;
  background: var(--sky);
  width: 280px;
  margin: 8px auto 0;
}

/* ---------- FEATURE GRID (HOME) ---------- */
.feature-row {
  display: grid;
  grid-template-columns: 8fr 4fr;
  gap: 24px;
  align-items: stretch;
}

.feature-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.feature-card {
  background: var(--bevel);
  color: var(--midnight);
  padding: 20px;
  border-top: 3px solid var(--bevel-light);
  border-left: 3px solid var(--bevel-light);
  border-bottom: 3px solid var(--shadow-edge);
  border-right: 3px solid var(--shadow-edge);
  outline: 1px solid var(--chrome);
}

.feature-card__icon {
  width: 44px;
  height: 44px;
  margin-bottom: 12px;
}

.feature-card__title {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 18px;
  text-transform: uppercase;
  color: var(--midnight);
  margin-bottom: 8px;
}

.feature-card__desc {
  color: #333;
  font-size: 13px;
  line-height: 1.6;
}

.feature-cta-strip {
  background: var(--lime);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  padding: 32px 16px;
  text-align: center;
  color: var(--midnight);
}

.feature-cta-strip__label {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 16px;
  letter-spacing: 0.04em;
}

.diagonal-bg {
  background-image:
    linear-gradient(135deg, rgba(102, 0, 204, 0.16) 25%, transparent 25%, transparent 50%, rgba(102, 0, 204, 0.16) 50%, rgba(102, 0, 204, 0.16) 75%, transparent 75%, transparent);
  background-size: 12px 12px;
}

/* ---------- TIMELINE (HOME) ---------- */
.timeline-stripe {
  padding: 56px 0;
  position: relative;
}
.timeline-stripe--grape { background: var(--grape); }
.timeline-stripe--midnight { background: var(--midnight); }

.timeline-stripe .container {
  display: grid;
  grid-template-columns: 2fr 7fr 3fr;
  gap: 24px;
  align-items: center;
}

.timeline-step__num {
  font-family: var(--font-pixel);
  font-size: 96px;
  line-height: 1;
  color: var(--honk);
}

.timeline-stripe--midnight .timeline-step__num {
  color: var(--magenta);
}

.timeline-step__label {
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--chrome);
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.timeline-step__title {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 26px;
  color: var(--lime);
  margin-bottom: 8px;
}

.timeline-stripe--grape .timeline-step__title {
  color: var(--bevel);
}

.timeline-step__desc {
  color: var(--bevel);
  font-size: 15px;
  max-width: 560px;
}

.timeline-callout {
  background: var(--honk);
  color: var(--midnight);
  font-family: var(--font-pixel);
  font-size: 13px;
  padding: 10px 12px;
  text-align: center;
  border-top: 2px solid var(--bevel-light);
  border-left: 2px solid var(--bevel-light);
  border-bottom: 2px solid var(--shadow-edge);
  border-right: 2px solid var(--shadow-edge);
}

.timeline-cta-bar {
  background: var(--lime);
  text-align: center;
  padding: 20px 0;
}

/* ---------- TESTIMONIALS ---------- */
.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: start;
}

.testimonial-grid > :nth-child(2) {
  margin-top: 32px;
}

.guestbook-card {
  background: var(--bevel);
  color: #222;
  border-top: 3px solid var(--bevel-light);
  border-left: 3px solid var(--bevel-light);
  border-bottom: 3px solid var(--shadow-edge);
  border-right: 3px solid var(--shadow-edge);
  outline: 1px solid var(--chrome);
}

.guestbook-card__title-bar {
  background: var(--chrome);
  color: var(--midnight);
  font-family: var(--font-pixel);
  font-size: 13px;
  padding: 4px 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--shadow-edge);
}

.guestbook-card__dots {
  display: flex;
  gap: 6px;
}

.guestbook-card__dots span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  border: 1px solid var(--midnight);
}

.guestbook-card__body {
  padding: 24px;
  position: relative;
}

.guestbook-card__quote-mark {
  font-family: 'Georgia', serif;
  font-size: 96px;
  line-height: 0.6;
  color: var(--magenta);
  position: absolute;
  top: 8px;
  left: 16px;
}

.guestbook-card__text {
  font-size: 14px;
  line-height: 1.7;
  color: #222;
  padding-left: 48px;
  margin-top: 4px;
}

.guestbook-card__rating {
  color: var(--honk);
  font-size: 18px;
  letter-spacing: 4px;
  margin: 12px 0 4px;
  padding-left: 48px;
  text-shadow: 1px 1px 0 var(--midnight);
}

.guestbook-card__author {
  padding-left: 48px;
  font-size: 13px;
  color: var(--midnight);
}

.guestbook-card__author .name {
  color: var(--sky);
  text-decoration: underline;
  font-weight: bold;
}

.guestbook-card__author .city {
  color: var(--shadow-edge);
}

.hit-counter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-pixel);
  font-size: 14px;
  color: var(--lime);
  background: #000;
  padding: 6px 12px;
  border-top: 2px solid var(--shadow-edge);
  border-left: 2px solid var(--shadow-edge);
  border-bottom: 2px solid var(--bevel);
  border-right: 2px solid var(--bevel);
  margin: 32px auto 0;
}

/* ---------- PRODUCT PAGE ---------- */
.product-masthead {
  background: var(--grape);
  position: relative;
  padding: 64px 0 48px;
  overflow: hidden;
}

.product-masthead::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(var(--midnight) 1.5px, transparent 1.5px);
  background-size: 14px 14px;
  opacity: 0.25;
  pointer-events: none;
}

.product-masthead__big-num {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 200px;
  line-height: 0.85;
  color: var(--lime);
  letter-spacing: -0.04em;
  -webkit-text-stroke: 4px var(--magenta);
  text-shadow: 6px 6px 0 var(--midnight);
  white-space: nowrap;
  margin-left: -8px;
}

.product-masthead__line2 {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 56px;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--bevel);
  line-height: 1;
  margin-top: -24px;
}

.product-masthead__sub {
  color: var(--bevel);
  font-size: 16px;
  margin-top: 24px;
  max-width: 520px;
}

/* Filter dashboard */
.filter-section {
  background: var(--bevel);
  color: var(--midnight);
  padding: 48px 0;
  border-top: 4px solid var(--shadow-edge);
  border-bottom: 4px solid var(--bevel-light);
}

.filter-section .section-header h2 { color: var(--midnight); }

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 24px 0;
}

.filter-card {
  background: var(--bevel);
  padding: 16px;
  border-top: 2px solid var(--bevel-light);
  border-left: 2px solid var(--bevel-light);
  border-bottom: 2px solid var(--shadow-edge);
  border-right: 2px solid var(--shadow-edge);
}

.filter-card__type {
  display: inline-block;
  border: 1px solid var(--grape);
  color: var(--grape);
  font-family: var(--font-pixel);
  font-size: 12px;
  text-transform: uppercase;
  padding: 1px 6px;
  margin-bottom: 8px;
}

.filter-card__title {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 18px;
  margin-bottom: 6px;
  color: var(--midnight);
}

.filter-card__desc {
  font-size: 13px;
  color: var(--midnight);
  opacity: 0.85;
  line-height: 1.5;
  margin-bottom: 10px;
}

.filter-input {
  width: 100%;
  padding: 6px 8px;
  font-family: var(--font-body);
  font-size: 14px;
  background: var(--bevel-light);
  border-top: 2px solid var(--shadow-edge);
  border-left: 2px solid var(--shadow-edge);
  border-bottom: 2px solid var(--bevel-light);
  border-right: 2px solid var(--bevel-light);
}

.filter-range {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-pixel);
  font-size: 12px;
}

.filter-range input { width: 70px; }

.filter-toggles {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.filter-toggles button {
  padding: 4px 10px;
  font-family: var(--font-pixel);
  font-size: 12px;
  background: var(--bevel);
  border-top: 2px solid var(--bevel-light);
  border-left: 2px solid var(--bevel-light);
  border-bottom: 2px solid var(--shadow-edge);
  border-right: 2px solid var(--shadow-edge);
  color: var(--midnight);
}

.filter-toggles button.is-on {
  background: var(--lime);
  border-top-color: var(--shadow-edge);
  border-left-color: var(--shadow-edge);
  border-bottom-color: var(--bevel-light);
  border-right-color: var(--bevel-light);
}

.filter-apply {
  width: 100%;
  background: var(--lime);
  color: var(--midnight);
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
  text-transform: uppercase;
  padding: 14px;
  text-align: center;
  border-top: 3px solid var(--bevel-light);
  border-left: 3px solid var(--bevel-light);
  border-bottom: 3px solid var(--shadow-edge);
  border-right: 3px solid var(--shadow-edge);
  text-decoration: none;
  display: block;
}

/* Inventory cards */
.inventory-section .section-header h2 {
  color: var(--lime);
  -webkit-text-stroke: 1px var(--magenta);
}

.inventory-header-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.live-counter {
  background: var(--bevel);
  border-top: 2px solid var(--bevel-light);
  border-left: 2px solid var(--bevel-light);
  border-bottom: 2px solid var(--shadow-edge);
  border-right: 2px solid var(--shadow-edge);
  padding: 8px 12px;
  font-family: var(--font-pixel);
  color: var(--midnight);
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.live-counter .num {
  color: var(--lime);
  font-size: 18px;
  background: #000;
  padding: 2px 6px;
}

.subhead-pixel {
  font-family: var(--font-pixel);
  font-size: 13px;
  color: var(--sky);
}

.car-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.car-card {
  background: var(--bevel);
  color: var(--midnight);
  position: relative;
  padding: 16px;
  padding-top: 28px;
  border-top: 3px solid var(--bevel-light);
  border-left: 3px solid var(--bevel-light);
  border-bottom: 3px solid var(--shadow-edge);
  border-right: 3px solid var(--shadow-edge);
}

.car-card__badge {
  position: absolute;
  top: -10px;
  left: -8px;
  background: var(--honk);
  color: var(--midnight);
  font-family: var(--font-pixel);
  font-size: 12px;
  padding: 3px 10px;
  text-transform: uppercase;
  border: 2px solid var(--midnight);
  letter-spacing: 0.1em;
  box-shadow: 2px 2px 0 var(--shadow-edge);
}

.car-card__photo {
  background: var(--chrome);
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--shadow-edge);
  margin-bottom: 12px;
}

.car-card__title {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 16px;
  margin-bottom: 4px;
}

.car-card__price {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 22px;
  color: var(--lime);
  -webkit-text-stroke: 1px var(--midnight);
  margin-bottom: 8px;
}

.car-card__desc {
  font-size: 12px;
  color: var(--midnight);
  opacity: 0.85;
  margin-bottom: 8px;
  line-height: 1.45;
}

.car-card__meta {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.car-card__meta span {
  font-family: var(--font-pixel);
  font-size: 12px;
  background: var(--bevel-light);
  border: 1px solid var(--chrome);
  padding: 1px 6px;
  color: var(--midnight);
}

.car-card__cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 13px;
}

.car-card__cta a.lime {
  color: #009900;
  font-weight: bold;
  text-decoration: underline;
}

/* Comparison */
.comparison {
  background: var(--midnight);
}

.comparison__top {
  text-align: center;
  padding: 20px 0;
}

.comparison__row {
  display: grid;
  grid-template-columns: 1fr 4px 1fr;
}

.comparison__col {
  padding: 32px 24px;
  color: var(--midnight);
}

.comparison__col--sedan { background: var(--honk); }
.comparison__col--suv { background: var(--sky); }
.comparison__col h3 {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 48px;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}

.comparison__metrics {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}

.metric-card {
  background: var(--bevel);
  padding: 12px;
  border-top: 2px solid var(--bevel-light);
  border-left: 2px solid var(--bevel-light);
  border-bottom: 2px solid var(--shadow-edge);
  border-right: 2px solid var(--shadow-edge);
}

.metric-card__label {
  font-family: var(--font-pixel);
  font-size: 12px;
  color: var(--grape);
  text-transform: uppercase;
}

.metric-card__value {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 28px;
  color: var(--midnight);
}

.comparison__divider {
  background: var(--chrome);
}

.comparison__col p {
  margin-bottom: 16px;
  max-width: 35ch;
}

.comparison__col .btn {
  background: var(--bevel);
  color: var(--midnight);
}

/* Magenta CTA close */
.cta-strip {
  background: var(--magenta);
  color: var(--midnight);
  text-align: center;
  padding: 0 0 56px;
  position: relative;
}

.cta-strip__marquee {
  background: var(--midnight);
  color: var(--honk);
  font-family: var(--font-pixel);
  font-size: 14px;
  padding: 8px 0;
  overflow: hidden;
  white-space: nowrap;
  margin-bottom: 56px;
}

.cta-strip h2 {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 56px;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--bevel);
  -webkit-text-stroke: 3px var(--midnight);
  line-height: 1;
  max-width: 900px;
  margin: 0 auto;
}

.cta-strip p {
  margin: 20px auto 0;
  max-width: 55ch;
  color: var(--midnight);
  font-size: 16px;
}

.cta-strip .btn--big {
  margin-top: 32px;
  background: var(--lime);
}

.cta-strip__badges {
  margin-top: 24px;
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* Specs page */
.specs-header {
  background: var(--grape);
  position: relative;
  padding: 64px 0 48px;
  overflow: hidden;
}

.specs-header::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(var(--midnight) 1px, transparent 1px), radial-gradient(var(--midnight) 1px, transparent 1px);
  background-size: 22px 22px;
  background-position: 0 0, 11px 11px;
  opacity: 0.18;
  pointer-events: none;
}

.specs-header__inner {
  display: grid;
  grid-template-columns: 6fr 5fr;
  gap: 32px;
  align-items: stretch;
  position: relative;
  z-index: 2;
}

.specs-header h1 {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  font-size: 52px;
  letter-spacing: -0.02em;
  line-height: 1;
  color: var(--magenta);
  text-shadow: 2px 2px 0 var(--midnight);
  margin-top: 12px;
}

.specs-header__sub {
  color: var(--bevel);
  font-size: 16px;
  margin-top: 16px;
  line-height: 1.65;
}

.specs-header__sub .lime { color: var(--lime); font-weight: bold; }

.dashboard-card {
  background: var(--bevel);
  color: var(--midnight);
  position: relative;
  border-top: 3px solid var(--bevel-light);
  border-left: 3px solid var(--bevel-light);
  border-bottom: 3px solid var(--shadow-edge);
  border-right: 3px solid var(--shadow-edge);
  outline: 1px solid var(--chrome);
  box-shadow: 8px 8px 0 var(--midnight);
}

.dashboard-card__header {
  background: var(--midnight);
  color: var(--lime);
  font-family: var(--font-pixel);
  font-size: 13px;
  padding: 6px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.dashboard-card__rows {
  padding: 12px 16px;
}

.dashboard-card__row {
  display: grid;
  grid-template-columns: 5fr 6fr;
  gap: 8px;
  padding: 6px 0;
  border-bottom: 1px dashed var(--chrome);
  align-items: baseline;
}

.dashboard-card__row:last-child {
  border-bottom: none;
}

.dashboard-card__label {
